TRANSLATIONS = {}
for code in LANGUAGES:
    category_catalog = {
        category_translation_key(category_key): display_name
        for category_key, display_name in zip(
            CATEGORY_KEYS,
            CATEGORY_TRANSLATIONS[code],
        )
    }
    catalog = {
        **_ENGLISH,
        **_CORE_TRANSLATIONS.get(code, {}),
        **_OPTION_TRANSLATIONS.get(code, {}),
        **_HOME_DESCRIPTION_TRANSLATIONS.get(code, {}),
        **_SIDEBAR_SETTING_TRANSLATIONS.get(code, {}),
        **_MARKETPLACE_TRANSLATIONS.get(code, {}),
        **_MARKETPLACE_PUBLICATION_TRANSLATIONS.get(code, {}),
        **_ENGINEERING_DRAWING_STUDIO_TRANSLATIONS.get(code, {}),
        **_ENGINEERING_PARAMETERS_TRANSLATIONS.get(code, {}),
        **category_catalog,
    }
    for removed_key in (
        "concept.visual_generation",
        "concept.leonardo_prompt",
        "concept.blueprint_prompt",
        "concept.generate_leonardo",
        "concept.generate_blueprint",
        "concept.generating_leonardo",
        "concept.generating_blueprint",
        "concept.leonardo_error",
        "concept.blueprint_error",
        "images.leonardo_asset",
        "images.leonardo_asset_description",
        "images.blueprint_asset",
        "images.blueprint_asset_description",
    ):
        catalog.pop(removed_key, None)
    if code != DEFAULT_LANGUAGE:
        for target_key, source_key in _TRANSLATION_ALIASES.items():
            catalog[target_key] = catalog[source_key]
        catalog.update(_FEATURE_TRANSLATIONS.get(code, {}))
    TRANSLATIONS[code] = catalog


def normalize_language(language):
    return language if language in LANGUAGES else DEFAULT_LANGUAGE


def translate(key, language=DEFAULT_LANGUAGE, **values):
    language = normalize_language(language)
    text = TRANSLATIONS.get(language, {}).get(key, _ENGLISH.get(key, key))
    return text.format(**values) if values else text


def category_display_name(category, language=DEFAULT_LANGUAGE):
    """Translate canonical or mapped legacy categories without inventing IDs."""
    category_key = normalize_category(category)
    if category_key is None:
        return " ".join(str(category or "").split())
    return translate(category_translation_key(category_key), language)


def language_display_name(language):
    language = normalize_language(language)
    return f"🌐 {LANGUAGES[language]['name']}"


def ai_language_name(language):
    language = normalize_language(language)
    return LANGUAGES[language]["ai_name"]
